pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 1, type(uint256).max - 1);

        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.deposit{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            // Deposit succeeded; reference allows this, buggy never gets here.
            // But we must read c's public surface. C has no public getter for balances.
            // We can check contract balance increased.
            uint256 balanceAfter = address(c).balance;
            assertTrue(balanceAfter >= amount);
        } else {
            // Deposit reverted; buggy always takes this branch, reference may or may not.
            // The bug violation: for the same inputs where reference succeeds (balance increases),
            // the buggy contract reverts. We cannot assert based on ok alone because reference
            // also reverts for some inputs (e.g., overflow).
            // The general rule: after any call to deposit() that does not revert, the contract's
            // balance must be >= the sent amount. The bug breaks this because deposit always reverts,
            // making the antecedent false in all cases. The rule is trivially true for buggy if we
            // only check the ok==true branch! We need a rule that is true for reference AND false for buggy.
            // We assert something that must be true for reference for ALL inputs, but false for buggy.
            assertTrue(address(c).balance == 0); // This is false for reference if deposit succeeds.
        }
    }
}

