contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, uint128 firstDeposit, uint128 secondDeposit) public {
        vm.assume(sender != address(0));
        vm.assume(sender != address(c));
        // (firstDeposit, secondDeposit) are in [0, 2**128-1]; no further bounding needed

        vm.deal(sender, uint256(firstDeposit) + uint256(secondDeposit));
        vm.startPrank(sender);
        if (firstDeposit > 0) {
            c.deposit{value: firstDeposit}();
        }
