        vm.stopPrank();

        // Compute total mapped balance across all known actors
        uint256 totalMapped;
        // sender's mapped balance (public mapping getter exists)
        totalMapped += c.balances(sender);
        // creator's mapped balance (was set to msg.sender of setUp, i.e., this contract)
        totalMapped += c.balances(address(this));
        // The contract's actual ether balance
        uint256 actualBalance = address(c).balance;

        assertTrue(totalMapped == actualBalance);
    }
}

