pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint160 actorSeed, uint96 depositVal, uint96 withdrawVal) public {
        address actor = address(actorSeed);
        vm.assume(actor != address(0));
        uint256 dep = uint256(depositVal);
        uint256 wd = uint256(withdrawVal);
        vm.assume(wd <= dep);

        // record initial balances and ETH
        uint256 initRecorded = c.balances(actor);
        uint256 initBalanceActor = actor.balance;
        uint256 initContractBalance = address(c).balance;

        // deposit
        vm.deal(actor, dep);
        vm.prank(actor);
        c.deposit{value: dep}();

        // withdraw part
        vm.prank(actor);
        c.withdraw(wd);

        // final balances
        uint256 finalRecorded = c.balances(actor);
        uint256 finalBalanceActor = actor.balance;
        uint256 finalContractBalance = address(c).balance;

        // expected changes
        uint256 recordedDelta = finalRecorded - initRecorded;
        uint256 actorEthDelta = finalBalanceActor - initBalanceActor;
        uint256 contractDelta = finalContractBalance - initContractBalance;

        // For the correct contract, recorded balance change equals deposited - withdrawn.
        // For the mutant, recorded balance is higher by 1 wei per deposit.
        // We check that recordedDelta * 1 == deposited - withdrawn does not hold; rather we check a derived invariant:
        // The contract's balance should reflect all net deposits (dep - wd) minus any extra leaked by mutant.
        // Since the mutant records +1, contract holds less than recorded sum.
        // Simple invariant: recordedDelta == (dep - wd) for correct contract. The mutant breaks this.
        assertTrue(recordedDelta == dep - wd);
    }
}

